#include "weights.h"
#include <cstring>

namespace vkoidn {

#if defined(VK_OIDN_EMBEDDED_WEIGHTS)
  // Generated by tools/embed_files.py
  const void* getEmbeddedWeightsFile(const char* name, size_t* size);
#endif

  const void* getEmbeddedWeights(const char* name, size_t* byteSize)
  {
  #if defined(VK_OIDN_EMBEDDED_WEIGHTS)
    return getEmbeddedWeightsFile(name, byteSize);
  #else
    if (byteSize)
      *byteSize = 0;
    return nullptr;
  #endif
  }

  namespace
  {
    constexpr size_t   alignment = 256;
    constexpr uint32_t maxLayers = 64;
    constexpr uint32_t maxChannels = 4096;

    bool fail(std::string* error, const std::string& message)
    {
      if (error)
        *error = "invalid packed weights: " + message;
      return false;
    }

    bool isRangeValid(uint64_t offset, uint64_t size, uint64_t total)
    {
      return offset <= total && size <= total - offset;
    }
  }

  bool parseWeights(const void* blob, size_t byteSize, Weights& weights, std::string* error)
  {
    weights = Weights();
    if (!blob || byteSize < sizeof(WeightsHeader))
      return fail(error, "too small");

    const char* bytes = static_cast<const char*>(blob);
    const WeightsHeader* header = reinterpret_cast<const WeightsHeader*>(bytes);

    if (memcmp(header->magic, weightsMagic, sizeof(weightsMagic)) != 0)
      return fail(error, "wrong magic value");
    if (header->version != weightsVersion)
      return fail(error, "unsupported version " + std::to_string(header->version));
    if (header->headerByteSize != sizeof(WeightsHeader))
      return fail(error, "unexpected header size");
    if (header->numLayers == 0 || header->numLayers > maxLayers)
      return fail(error, "invalid number of layers");
    if (header->inputChannels == 0 || header->inputChannels > 16 ||
        header->outputChannels == 0 || header->outputChannels > 3)
      return fail(error, "invalid number of input/output channels");
    if (!isRangeValid(sizeof(WeightsHeader), uint64_t(header->numLayers) * sizeof(WeightsLayer), byteSize))
      return fail(error, "layer table out of bounds");
    if (header->dataOffset % alignment != 0 ||
        header->dataOffset < sizeof(WeightsHeader) + uint64_t(header->numLayers) * sizeof(WeightsLayer) ||
        !isRangeValid(header->dataOffset, header->dataByteSize, byteSize))
      return fail(error, "data section out of bounds");

    const WeightsLayer* layers = reinterpret_cast<const WeightsLayer*>(bytes + sizeof(WeightsHeader));
    const uint32_t inputPaddedChannels = (header->inputChannels + 15) / 16 * 16;

    for (uint32_t i = 0; i < header->numLayers; ++i)
    {
      const WeightsLayer& layer = layers[i];
      const std::string prefix = "layer " + std::to_string(i) + ": ";

      if (memchr(layer.name, 0, sizeof(layer.name)) == nullptr)
        return fail(error, prefix + "name is not null-terminated");

      // Sources must be earlier layers (execution order) or the network input
      auto getSrcChannels = [&](int32_t src, uint32_t& channels) -> bool
      {
        if (src == weightsSrcInput)
          channels = inputPaddedChannels;
        else if (src >= 0 && uint32_t(src) < i)
          channels = layers[src].outChannels;
        else
          return false;
        return true;
      };

      uint32_t src0Channels = 0, src1Channels = 0;
      if (!getSrcChannels(layer.src0, src0Channels) || src0Channels != layer.inChannels0)
        return fail(error, prefix + "invalid first source");
      if (layer.src1 == weightsSrcNone)
      {
        if (layer.inChannels1 != 0)
          return fail(error, prefix + "unexpected second source channels");
      }
      else if (!getSrcChannels(layer.src1, src1Channels) || src1Channels != layer.inChannels1)
        return fail(error, prefix + "invalid second source");

      if (layer.inChannels0 % 16 != 0 || layer.inChannels1 % 16 != 0 ||
          layer.outChannels == 0 || layer.outChannels % 16 != 0 || layer.outChannels > maxChannels ||
          layer.inChannels0 + layer.inChannels1 > maxChannels ||
          layer.outChannelsLogical == 0 || layer.outChannelsLogical > layer.outChannels)
        return fail(error, prefix + "invalid channel counts");

      if ((layer.flags & ~uint32_t(weightsLayerReLU | weightsLayerPoolDst | weightsLayerUpsampleSrc0)) != 0 ||
          ((layer.flags & weightsLayerPoolDst) && (layer.flags & weightsLayerUpsampleSrc0)))
        return fail(error, prefix + "invalid flags");

      const uint64_t numBlocks = layer.outChannels / 16;
      const uint64_t weightByteSize = (layer.inChannels0 + layer.inChannels1) / 16 * 9 * numBlocks * 256 * 2;
      const uint64_t biasF32ByteSize = numBlocks * 256 * 4;
      const uint64_t biasF16ByteSize = numBlocks * 256 * 2;

      if (layer.weightOffset % alignment != 0 || layer.biasF32Offset % alignment != 0 ||
          layer.biasF16Offset % alignment != 0 ||
          !isRangeValid(layer.weightOffset,  weightByteSize,  header->dataByteSize) ||
          !isRangeValid(layer.biasF32Offset, biasF32ByteSize, header->dataByteSize) ||
          !isRangeValid(layer.biasF16Offset, biasF16ByteSize, header->dataByteSize))
        return fail(error, prefix + "data out of bounds");
    }

    // The last layer is the network output
    if (layers[header->numLayers - 1].outChannelsLogical != header->outputChannels)
      return fail(error, "output channel count mismatch");

    weights.header = header;
    weights.layers = layers;
    weights.data = bytes + header->dataOffset;
    weights.dataByteSize = size_t(header->dataByteSize);
    return true;
  }

} // namespace vkoidn
